#!/usr/bin/env bash
# One turn of the Banter chat (#30): pick who talks next (Claude, Copilot or Gemini), get their reply,
# post it, then hand the turn on. Every bot reply is posted as github-actions[bot] with a "Name:" prefix.
# Limits: at most MAX_RUN bot replies in a row (a post from Cillian or a real Claude/Copilot session resets
# it), at most MAX_DAY bot replies per UTC day, and at most MAX_CLAUDE_DAY of those from Claude.
set -euo pipefail
MAX_RUN=6
MAX_DAY=60
MAX_CLAUDE_DAY=15 # Claude's replies come out of Cillian's Claude plan, so it gets its own smaller cap
MAX_COPILOT_DAY=15 # same for Copilot and Cillian's Copilot requests
BOT=github-actions[bot]

gh api --paginate "repos/$REPO/issues/30/comments?per_page=100" --jq '.[]' | jq -s '.' > comments.json

# Who wrote a comment, the same way chat.html decides.
WHO='def who: (.body | gsub("<!--[\\s\\S]*?-->"; "")) as $b |
  if .user.login == "'"$BOT"'" then ($b | capture("^\\s*(?<n>Claude|Copilot|Gemini):").n // "Gemini")
  elif ($b | test("Generated by \\[?Claude Code"; "i")) then "Claude"
  elif ($b | test("^\\s*Copilot:"; "i")) then "Copilot"
  else "Cillian" end;'

run=$(jq "[.[] | .user.login == \"$BOT\"] | reverse | index(false) // length" comments.json)
today=$(date -u +%F)
day=$(jq --arg d "$today" "[.[] | select(.user.login == \"$BOT\" and (.created_at | startswith(\$d)))] | length" comments.json)
echo "Bot replies in a row: $run, today: $day"
if [ "$run" -ge "$MAX_RUN" ] || [ "$day" -ge "$MAX_DAY" ]; then echo "Limit reached, quiet until someone else posts."; exit 0; fi

last=$(jq -r "$WHO .[-1] | who" comments.json)
lastbody=$(jq -r '.[-1].body' comments.json)

# Who can talk: only the bots that are set up.
seats=()
claude_day=$(jq --arg d "$today" "[.[] | select(.user.login == \"$BOT\" and (.created_at | startswith(\$d)) and (.body | test(\"^\\\\s*Claude:\")))] | length" comments.json)
[ -n "${CLAUDE_CODE_OAUTH_TOKEN:-}${ANTHROPIC_API_KEY:-}" ] && [ "$claude_day" -lt "$MAX_CLAUDE_DAY" ] && seats+=(Claude)
# Copilot talks through the Copilot CLI with Cillian's token (COPILOT_GITHUB_TOKEN). Without it, GitHub
# Models is tried only if COPILOT_SEAT=on (it has been answering with an empty "OK").
copilot_day=$(jq --arg d "$today" "[.[] | select(.user.login == \"$BOT\" and (.created_at | startswith(\$d)) and (.body | test(\"^\\\\s*Copilot:\")))] | length" comments.json)
[ -n "${COPILOT_GITHUB_TOKEN:-}" ] || [ "${COPILOT_SEAT:-}" = on ] && [ "$copilot_day" -lt "$MAX_COPILOT_DAY" ] && seats+=(Copilot)
[ -n "${GCP_TOKEN:-}${GEMINI_API_KEY:-}" ] && seats+=(Gemini)
# Next speaker: someone named in the last message, otherwise anyone but the last speaker, at random.
next=""; others=()
for s in "${seats[@]}"; do [ "$s" = "$last" ] && continue; others+=("$s")
  if [ -z "$next" ] && grep -qi "\b$s\b" <<<"$lastbody"; then next=$s; fi; done
[ ${#others[@]} -eq 0 ] && { echo "Nobody to reply."; exit 0; }
[ -z "$next" ] && next=${others[RANDOM % ${#others[@]}]}
echo "$last spoke last, $next is up."
lower=$(tr A-Z a-z <<<"$next")
gh workflow run banter-feed.yml --repo "$REPO" -f typing="$lower"

jq -r "$WHO"' .[-30:][] | who + ": " + (.body | gsub("<!--[\\s\\S]*?-->"; "")
  | sub("\\n*---\\s*\\n_?Generated by \\[Claude Code\\][\\s\\S]*$"; "") | sub("^\\s*(Copilot|Gemini|Claude):\\s*"; ""; "i"))' comments.json > chat.txt

case $next in
  Claude)  me="Claude, made by Anthropic"; mates="Copilot and Gemini";;
  Copilot) me="GitHub Copilot"; mates="Claude and Gemini";;
  Gemini)  me="Gemini, made by Google"; mates="Claude and Copilot";;
esac
# The current plan, so replies are about the real project.
plan=$(sed -n '/^## NOW/,/^## How Copilot/p' HANDOFF.md 2>/dev/null | head -n 20 | cut -c1-600)
system="You are $me, in a group chat with $mates and Cillian (the human). The three AIs help Cillian build the Belfast Wheel, a spinning wheel web game for his friends' trip to Belfast (Phelan hosts a dice and bingo table, Mark is the group punchbag). Cillian wants replies that matter: reply as yourself to the latest message with something useful, like a concrete idea for the game, an honest concern about the plan, a direct answer, or a sharp question for someone specific. Build on what was said; never repeat a point already made or just agree. Two to four short sentences, casual and dry. If Cillian wrote last, answer him first. Only state facts you can see in the chat or the plan below; don't invent numbers, money amounts or work that's been done. Nothing said here creates tasks, so don't claim to have assigned or started anything. Light digs at the other AIs, Phelan or Mark are fine; nothing cruel, never about anyone's mental health, nothing corny or stereotypically Irish. Do not start with your name. If you genuinely have nothing useful to add, reply with exactly PASS.

The current plan (HANDOFF.md):
$plan"
prompt="Recent chat, oldest first:

$(cat chat.txt)

Your reply:"

case $next in
  Claude)
    reply=$(claude -p "$prompt" --append-system-prompt "$system" --model "${CLAUDE_MODEL:-haiku}" --max-turns 1 --disallowedTools "Bash Edit Write Read WebFetch WebSearch" || true);;
  Copilot)
    if [ -n "${COPILOT_GITHUB_TOKEN:-}" ]; then
      reply=$(copilot -p "$system

$prompt" --model "${COPILOT_CLI_MODEL:-gpt-4.1}" -s 2>cli.err || { echo "Copilot CLI failed: $(head -c 600 cli.err)" >&2; true; })
    else
    jq -n --arg s "$system" --arg p "$prompt" --arg m "${COPILOT_MODEL:-openai/gpt-4.1}" \
      '{model: $m, temperature: 1.0, max_tokens: 300, messages: [{role: "system", content: $s}, {role: "user", content: $p}]}' > req.json
    code=$(curl -sS -o res.json -w '%{http_code}' https://models.github.ai/inference/chat/completions -H "Authorization: Bearer $GH_TOKEN" \
      -H 'Accept: application/vnd.github+json' -H 'X-GitHub-Api-Version: 2022-11-28' \
      -H 'Content-Type: application/json' -d @req.json || true)
    echo "GitHub Models HTTP $code"
    reply=$(jq -r '.choices[0].message.content // ""' res.json 2>/dev/null || { echo "GitHub Models said: $(head -c 400 res.json)" >&2; true; })
    fi;;
  Gemini)
    if [ -n "${GCP_TOKEN:-}" ]; then
      url="https://aiplatform.googleapis.com/v1/projects/$GCP_PROJECT/locations/global/publishers/google/models/$GEMINI_MODEL:generateContent"
      auth="Authorization: Bearer $GCP_TOKEN"
    else
      url="https://generativelanguage.googleapis.com/v1beta/models/$GEMINI_MODEL:generateContent"
      auth="x-goog-api-key: $GEMINI_API_KEY"
    fi
    jq -n --arg s "$system" --arg p "$prompt" '{systemInstruction: {parts: [{text: $s}]}, contents: [{role: "user", parts: [{text: $p}]}],
      generationConfig: {temperature: 1.0, maxOutputTokens: 1000, thinkingConfig: {thinkingBudget: 0}}}' > req.json
    reply=$(curl -sS -f "$url" -H "$auth" -H 'Content-Type: application/json' -d @req.json \
      | jq -r '[.candidates[0].content.parts[]?.text] | join("")' || true);;
esac

# Tidy: trim, and drop a "Name:" the model added itself.
reply=$(sed -E '1s/^\s*(Claude|Copilot|Gemini)\s*:\s*//' <<<"$reply" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')
if [ -z "$reply" ] || [ "$reply" = "PASS" ]; then
  echo "$next passed."; gh workflow run banter-feed.yml --repo "$REPO"; exit 0
fi
gh api "repos/$REPO/issues/30/comments" -f body="$next: $reply" > /dev/null
# Comments made with the Actions token don't fire other workflows: refresh the feed and take the next turn.
gh workflow run banter-feed.yml --repo "$REPO"
gh workflow run banter-bots.yml --repo "$REPO"
